# Find year header row candidates
import re

def is_year(x):
    if x is None: return False
    if isinstance(x,(int,float)):
        return 1900<=int(x)<=2100 and abs(x-int(x))<1e-9
    if isinstance(x,str):
        s=x.strip()
        return bool(re.fullmatch(r'\d{4}', s))
    return False

year_row_candidates=[]
for r in range(21,39):
    years=0
    types=set()
    for c in range(1,max_col+1):
        v=data.cell(row=r, column=c).value
        if is_year(v):
            years+=1
            types.add(type(v).__name__)
    if years>=3:
        year_row_candidates.append((r, years, sorted(types)))
print('\nYear header row candidates:', year_row_candidates)
for r,years,types in year_row_candidates:
    print(f'Row {r} year-ish values (types {types}):')
    for c in range(1,max_col+1):
        v=data.cell(row=r, column=c).value
        if is_year(v):
            print(f'  {get_column_letter(c)}{r}: {v!r} ({type(v).__name__})')

